contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val1, uint256 val2) public payable {
        // Before initialization, SetMinSum must succeed and set MinSum to the argument.
        c.SetMinSum(val1); if (__ESBMC_reverted()) return;
        uint256 afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        // Set initialized to true.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // After initialization, any further SetMinSum call must revert and MinSum must stay unchanged.
        bool reverted;
        c.SetMinSum(val2); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && afterFirst == val1 && c.MinSum() == val1);
    }

    receive() external payable {}
}

